import {categories} from './data.js';
import {recipeRepository as repo} from './repository.js';
import {shell,escapeHTML as e,toast,fatal} from './ui.js';
shell('');const form=document.querySelector('#recipe-form');let photo='',photoBusy=false,dirty=false,original;const editId=new URLSearchParams(location.search).get('id');
document.querySelector('#category').innerHTML=categories.slice(1).map(c=>`<option>${e(c)}</option>`).join('');
function renumber(){document.querySelectorAll('.step-row').forEach((row,i)=>{row.querySelector('.step-number').textContent=String(i+1).padStart(2,'0');row.querySelector('textarea').setAttribute('aria-label',`Крок ${i+1}`);});for(const selector of ['.step-row','.ingredient-row']){const rows=document.querySelectorAll(selector);rows.forEach(row=>row.querySelector('.row-remove').hidden=rows.length===1);}}
function addIngredient(i={name:'',amount:'',unit:''},focus=false){const row=document.createElement('div');row.className='ingredient-row';row.innerHTML=`<input class="ing-name" aria-label="Назва інгредієнта" required maxlength="150" placeholder="Наприклад, борошно" value="${e(i.name)}"><input class="ing-amount" aria-label="Кількість" type="number" min="0" max="100000" step="any" placeholder="200" value="${i.amount||''}"><input class="ing-unit" aria-label="Одиниця виміру" maxlength="30" placeholder="г" value="${e(i.unit)}"><button type="button" class="row-remove" aria-label="Видалити інгредієнт">×</button>`;row.querySelector('button').onclick=()=>{row.remove();dirty=true;renumber();};document.querySelector('#ingredient-rows').append(row);renumber();if(focus)row.querySelector('input').focus();}
function addStep(text='',focus=false){const row=document.createElement('div');row.className='step-row';row.innerHTML=`<span class="step-number"></span><textarea required maxlength="3000" rows="2" placeholder="Опишіть просту дію…">${e(text)}</textarea><button type="button" class="row-remove" aria-label="Видалити крок">×</button>`;row.querySelector('button').onclick=()=>{row.remove();dirty=true;renumber();};document.querySelector('#step-rows').append(row);renumber();if(focus)row.querySelector('textarea').focus();}
function showPhoto(){const preview=document.querySelector('#photo-preview');preview.hidden=!photo;preview.src=photo||'';document.querySelector('#photo-placeholder').hidden=!!photo;document.querySelector('#remove-photo').hidden=!photo;}
function initialize(){try{if(editId){original=repo.get(editId);if(!original){document.querySelector('main').innerHTML='<div class="empty"><h1>Рецепт не знайдено</h1><a class="button" href="index.html">До колекції</a></div>';return;}document.title=`Редагування: ${original.title} — Смак`;document.querySelector('#form-title').textContent='Додайте ще трішки смаку.';for(const key of ['title','description','category','time','servings','notes'])form.elements[key].value=original[key];photo=original.image;showPhoto();original.ingredients.forEach(i=>addIngredient(i));original.steps.forEach(s=>addStep(s));}else{repo.list();addIngredient();addIngredient();addStep();}}catch(err){fatal(err);}}
document.querySelector('#add-ingredient').onclick=()=>{addIngredient(undefined,true);dirty=true;};document.querySelector('#add-step').onclick=()=>{addStep('',true);dirty=true;};
form.addEventListener('input',()=>dirty=true);window.addEventListener('beforeunload',ev=>{if(dirty){ev.preventDefault();ev.returnValue='';}});
document.querySelector('#remove-photo').onclick=()=>{photo='';document.querySelector('#photo').value='';showPhoto();dirty=true;};
document.querySelector('#photo').onchange=async ev=>{const file=ev.target.files[0];if(!file)return;photoBusy=true;document.querySelector('#save-button').disabled=true;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024)throw new Error('Оберіть JPG, PNG або WebP розміром до 10 МБ.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);photo=canvas.toDataURL('image/jpeg',.78);bitmap.close();showPhoto();dirty=true;}catch(err){toast(err.message||'Не вдалося прочитати фото.',true);ev.target.value='';}finally{photoBusy=false;document.querySelector('#save-button').disabled=false;}};
form.onsubmit=ev=>{ev.preventDefault();if(photoBusy)return;const error=document.querySelector('#form-error');error.textContent='';try{const recipe={id:original?.id||crypto.randomUUID(),title:form.elements.title.value.trim(),description:form.elements.description.value.trim(),category:form.elements.category.value,time:Number(form.elements.time.value),servings:Number(form.elements.servings.value),notes:form.elements.notes.value.trim(),image:photo,favorite:original?.favorite||false,createdAt:original?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),demo:false,ingredients:[...document.querySelectorAll('.ingredient-row')].map(row=>({name:row.querySelector('.ing-name').value.trim(),amount:Number(row.querySelector('.ing-amount').value),unit:row.querySelector('.ing-unit').value.trim()})),steps:[...document.querySelectorAll('.step-row textarea')].map(t=>t.value.trim())};repo.upsert(recipe);dirty=false;location.href=`recipe.html?id=${encodeURIComponent(recipe.id)}&saved=1`;}catch(err){error.textContent=err.message;error.scrollIntoView({block:'center',behavior:'smooth'});}};
initialize();
